style.css:
@-moz-document domain("thecrag.com") {
:root {
        --bg1: #0E0D0B;
        --bg2: #141310;
        --bg3: #1B1917;
        --bg4: #23201D;
        --bg5: #2B2924;
        --bg6: #34322D;
        --bg7: #3E3C37;
        --bg8: #484641;
        --bg9: #53504C;
        --bg10: #5E5A57;
        
        --text1: #C8C3BD;
        --text2: #A59F98;
        --text3: #807970;
        --text4: #6D675F;
        --text5: #3B3834;

        --darken-img: saturate(1.3) brightness(0.7);
    }

    body {
        color: var(--text2);
        background-color: var(--bg7) !important;
    }

    .bust__white {
        background: var(--bg6);
    }

    .bust__black {
        background: var(--bg4);
    }

    .crumb__a {
        color: var(--text2);
    }

    .crumb--selected>a {
        color: var(--text1);
    }

    .crumb__a:hover {
        color: var(--text1);
        background: var(--bg2);
    }

    .crumb--menu:hover {
        color: var(--text1);
        background: inherit;
    }

    .bust__search {
        background: inherit;
    }

    .search-form input {
        color: #ccc;
        background: var(--bg9);
        border-color: var(--bg9);
    }

    .search-form .go {
        background: var(--bg10);
        border-color: var(--bg10);
        color: var(--text2);
    }

    .search-form input:focus {
        background: var(--bg6);
        color: var(--text1);
    }

    .tabs {
        background: inherit;
    }

    .tabs::before, .tabs::after {
        background-image: none;
    }

    .tab>a {
        color: var(--text2);
    }

    .tab--selected>a {
        border-color: var(--bg1);
    }

    a.iblock.ablock>img {
        filter: brightness(0.6);
    }

    .regions__navdrawer {
        background: var(--bg6);
    }

    .nav {
        background: inherit;
    }

    .nav__group {
        color: var(--text2);
        text-shadow: 0 1px 0 rgba(0, 0, 0, 0.5);
    }

    .nav__a a {
       color: var(--text3);
    }

    .nav__a--selected a {
        background: var(--bg3);
        color: var(--text1);
    }

    .nav__a--selected:hover a {
        background: none;
    }

    .hoverable:hover {
        background: var(--bg1);
    }

    .hoverable:hover>a {
        background: inherit;
        color: var(--text2);
    }

    .nav__div {
        background-color: var(--bg5);
        border-bottom: 1px solid var(--bg6);
    }

    .regions__content {
        background-image: linear-gradient(to bottom, var(--bg7) 0, var(--bg9) 6px, var(--bg8) 100px);
    }

    h1, h2, h3, h4, h5, h6 {
        color: var(--text2);
    }

    a {
        color: var(--text4);
    }

    a:hover {
        color: var(--text1);
        background-color: var(--bg4);
    }

    .stream a.event-when {
        color: var(--text3);
    }

    table {
        background-color: var(--bg6);
    }

    th {
        background: var(--bg5);
    }

    .btn {
        background-color: var(--bg9);
        background-image: none;
        color: var(--text2);
        text-shadow: 0 1px 1px rgba(0, 0, 0, 0.75);
    }

    .btn:hover {
        color: var(--text4);
        background-color: var(--bg10);
    }

    .stream .calendar-date {
        border: 1px solid var(--bg19);
        background: var(--bg6);
        color: var(--text2);
    }

    .stream .calendar-date>.day {
        background: var(--bg4);
    }

    .stream .event:before {
        border-top: 1px solid var(--bg3);
    }

    .stream .event-type {
        background: var(--bg6);
        border: 1px solid var(--bg3);
    }

    .stream {
        border-left: 1px solid var(--bg3);
    }

    a:hover .face__b {
        border-color: var(--text4);
    }

    .markdown del {
        background: #8e2525;
        color: var(--text1);
    }

    .markdown ins {
        background: #187118;
        color: var(--text1);
    }

    .dropdown-menu {
        background-color: var(--bg6);
    }
    .dropdown-menu .nav-header {
        color: var(--text1);
    }

    .nav-header {
        text-shadow: 0 1px 0 rgba(0, 0, 0, 0.5);
    }

    .dropdown-menu li>a {
        color: var(--text2);
    }

    .dropdown-menu .divider {
        background-color: var(--bg5);
        border-bottom: 1px solid var(--bg6);
    }

    .dropdown-menu li>a:hover, .dropdown-menu li>a:focus, .dropdown-submenu:hover>a {
        background-color: var(--bg3);
        background-image: none;
    }

    .btn-group.open .btn.dropdown-toggle {
        background-color: var(--bg10);
    }

    .bg-brand-blue {
        background-color: var(--bg6);
    }

    .tab:hover>a {
        background: var(--bg4);
        border-color: var(--bg1);
    }

    .bubble-top-left::after, .bubble-top-right::after {
        border-bottom-color: var(--bg6);
    }

    a[rel=prev], a[rel=next] {
        color: var(--text2);
        background: var(--bg5);
    }

    .btn-flat, .btn-flat:hover {
        color: var(--text4) !important;
    }

    .heading__t {
        color: var(--text1);
    }

    .secondary-navigation ul li a {
        background: var(--bg6);
        color: var(--text3);
    }

    .secondary-navigation .group, .secondary-navigation li.top>a {
        border-bottom: 1px solid var(--bg4);
    }

    .secondary-navigation .embed-menu li>a:hover, .secondary-navigation li.selected>a, .secondary-navigation a:hover, .secondary-navigation a.active:hover, .secondary-navigation a:focus {
        color: var(--text2);
        background-color: var(--bg1);
        background-image: none;
    }

    .dropdown-submenu>a:after {
        border-left-color: var(--bg1);
    }

    .dropdown-submenu:hover>a:after {
        border-left-color: var(--bg5);
    }

    .node-info.expandable .content {
        background-image: none;
    }

    table.barchat-v {
      background: inherit;
    }

    .node-listview .header {
        background: var(--bg7);
    }

    .node-listview>.area {
        border-color: var(--bg5);
    }

    .node-listview>.hover, .node-listview>.route.hover  {
        background: var(--bg7);
        border-color: var(--bg1) !important;
    }

    .secondary-navigation a.active, .recommendtable tbody tr.hover td, .recommendtable tbody tr:hover td, .routetable tbody tr.hover td, .routetable tbody tr:hover td, .areatable tbody tr.hover td, .areatable tbody tr:hover td, tr:target td {
        background: var(--bg7);
        color: var(--text2);
    }

    .tags {
        background: #DDD !important;
    }

    .icontag {
        background: #DDD;
    }

    .icontag:hover {
        background: var(--bg1);
    }

    .node-listview>.selected {
        background: var(--bg6);
        color: var(--text1);
    }

    .node-listview>.route.hover .sticky-header {
        background: var(--bg7);
    }

    .node-listview>.route .sticky-header {
        background: var(--bg8);
    }

    .node-listview>.route {
        background: var(--bg8);
        border-color: var(--bg5);
    }

    .form-actions {
        background: var(--bg8);
    }

    .btn-primary.disabled, .btn-primary[disabled] {
        color: var(--text3);
        background-color: var(--bg6);
    }

    .btn-primary:hover, .btn-primary:active, .btn-primary.active {
        color: var(--text4);
        background-color: var(--bg10);
    }

    .alert {
        text-shadow: 0 1px 0 rgba(0, 0, 0, 0.5);
        background-color: #605916;
        border: none;
        color: var(--text1);
    }

    .alert.alert-new {
        background-color: #b84f00;
        color: var(--text1);
        border: 4px solid rgba(0, 0, 0, 0.2);
    }

    @media only screen and (min-width: 915px) {
        .node-listview .desc.brief>* {
            border-color: var(--bg4);
        }
    }

    .gb {
        color: var(--bg6);
    }

    .icon-pitches {
        filter: invert(1);
    }

    .leaflet-popup-content-wrapper, .leaflet-popup-tip {
        background: var(--bg8);
        color: var(--text2);
    }

    .tcm-popup .leaflet-popup-content a.btn {
        color: var(--text2);
    }

    .gear-style-unknown, .gear-style-trad, .gear-style-sport,
    .gear-style-dws, .gear-style-aid, .gear-style-via-ferrata,
    .gear-style-boulder, .gear-style-ice, .gear-style-alpine,
    .gear-style-top-rope, .gear-style-traverse, .gear-style-second,
    .gear-style-solo {
      filter: invert(0.8);
    }

    .label-aka, .label-redirect, .label-attribute, .label-beta, 
    .label-diary, .label-climbers, .label-geo, .label-grade, 
    .label-stars, .label-tags, .label-areatype, .label-stub, 
    .label-insert-before, .label-name, .label-annotation-title, 
    .label-context, .label-general {
        background-color: var(--bg7);
        color: var(--text1);
    }

    form input, form select, form textarea {
        background: #444;
        border: 1px solid #555;
        color: var(--text1);
    }

    input:focus, select:focus, textarea:focus {
        background: #AAA;
        color: var(--text5);
    }

    .select2-container-multi .select2-choices {
        color: #444;
        background-image: none;
        border-color: #444;
    }

    .update-element {
        border: 2px solid var(--bg6);
    }

    .update-element:hover {
        border-color: var(--bg1);
    }

    .update-element:hover .update-path {
        background-color: var(--bg1);
        color: var(--text1);
    }

    .update-path {
        background: var(--bg5);
    }

    .beta-cell {
        background-color: var(--bg5);
    }

    .markedup {
        background: var(--bg7);
        border-color: var(--bg1);
    }
    .select2-drop-active {
        border: 1px solid #5897fb;
        border-top: none;
        border-color: var(--bg2);
    }

    .select2-container-multi .select2-choices {
        border: 1px solid #444;
        background-color: #444;
    }

    .select2-drop-active {
        border-color: var(--bg2);
    }

    .select2-drop {
        background: var(--bg5);
        color: var(--text2);
    }

    .select2-results .select2-highlighted {
        background: var(--bg2);
    }

    .select2-container-multi .select2-choices .select2-search-choice {
        color: var(--text2);
        background-color: var(--bg10);
        border-color: var(--bg8);
        background-image: none;
    }

    #login #btnLogin, .standardButton input, .exceptionButton input,
    .offsetButton input {
        text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.5);
        background-color: var(--bg9);
        background-image: none;
        color: var(--text2);
        border-color: var(--bg9);
    }

    #login #btnLogin, .defaultButton input, .standardButton input:hover,
    .standardButton input.selected, .offsetButton input:hover {
        background-color: var(--bg10);
        color: var(--text1);
        border-color: var(--bg10);
        border-bottom-color: rgba(255, 255, 255, 0.1);
        text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.5);
    }

    .well {
        background-color: var(--bg7);
        border-color: var(--bg5);
    }

    .bs-form textarea, .bs-form input[type="text"], .bs-form input[type="password"], 
    .bs-form input[type="datetime"], .bs-form input[type="datetime-local"], 
    .bs-form input[type="date"], .bs-form input[type="month"], 
    .bs-form input[type="time"], .bs-form input[type="week"], 
    .bs-form input[type="number"], .bs-form input[type="email"], 
    .bs-form input[type="url"], .bs-form input[type="search"], 
    .bs-form input[type="tel"], .bs-form input[type="color"], 
    .bs-form .uneditable-input {
        background-color: var(--bg5);
        border-color: var(--bg4);
    }

    .bs-form select, .bs-form textarea, .bs-form input[type="text"], 
    .bs-form input[type="password"], .bs-form input[type="datetime"], 
    .bs-form input[type="datetime-local"], .bs-form input[type="date"], 
    .bs-form input[type="month"], .bs-form input[type="time"], 
    .bs-form input[type="week"], .bs-form input[type="number"], 
    .bs-form input[type="email"], .bs-form input[type="url"], 
    .bs-form input[type="search"], .bs-form input[type="tel"], 
    .bs-form input[type="color"], .bs-form .uneditable-input {
        color: var(--text2);
    }

    .routetable th, .areatable th {
        background: var(--bg7);
        border-color: var(--bg4);
    }

    .routetable td, .areatable td {
        border-color: var(--bg4);
    }

    .card {
        background: var(--bg10);
    }

    .card svg.fill path {
        fill: var(--bg5);
        stroke: var(--bg3);
    }

    .ablock, .aiblock {
        color: var(--text2);
    }

    .card-climber__head {
        background: var(--bg9);
    }

    .bigstats dl {
        color: var(--text2);
    }

    a.card:hover {
        background: var(--bg7);
    }

    .quick-toc {
        background: var(--bg6);
    }

    .quick-toc.quick-toc--float {
        border-color: var(--bg4);
    }

    .figure {
        border-color: var(--bg5);
    }

    .face__b {
        background: var(--bg8);
    }

    tbody tr.alternate td {
        background: var(--bg5);
    }

    #login #btnLogin, .defaultButton input, .standardButton input:hover, 
    .standardButton input.selected, .offsetButton input:hover {
        background-image: none;
    }

    legend {
        color: var(--text2);
        background: var(--bg10);
    }

    fieldset {
        border-color: var(--bg10);
        border-style: solid;
    }

    #footer h4 {
        color: var(--text4);
    }

    #footer a {
        color: var(--text2);
    }

    .leaflet-control-layers-expanded {
        color: var(--text2);
        background: var(--bg8);
    }

    .band--words {
        filter: saturate(0.5) brightness(0.8);
    }

    #facets {
        background: var(--bg7);
        border-color: var(--bg4);
    }

    .pagination ul>li>a:hover, .pagination ul>.active>a, .pagination ul>.active>span {
        color: var(--text1);
        background-color: var(--bg1);
        border-color: var(--bg1);
    }

    .pagination ul>li>a, .pagination ul>li>span {
        background-color: var(--bg7);
        border-color: var(--bg4);
    }

    .pagination ul>.disabled>span, .pagination ul>.disabled>a, .pagination ul>.disabled>a:hover {
        color: var(--text3);
        background-color: var(--bg7);
        opacity: 0.6;
    }

    .grade-slider-title {
        background: var(--bg10);
        border-color: var(--bg10);
    }

    .grade-slider-systems {
        border: 1px solid var(--bg10);
    }

    .rank {
        color: var(--text3);
    }

    .bg-pale {
        background: var(--bg6);
    }

    .btn.active, .btn:active {
        background-color: var(--bg9);
        color: var(--text4);
    }

    .forum .discussion {
        border-color: var(--bg4);
        background: var(--bg7);
    }

    .forum .discussion-header {
        background-color: var(--bg7);
        background-image: none;
    }

    .badge {
        filter: brightness(0.8);
    }

    .forum .comment-content.unread {
        background: var(--bg6);
    }

    .forum .comment-content>div {
        border-color: var(--bg4);
    }

    .forum .comment-content a {
        color: var(--text4);
    }

    a .climber__name {
        filter: contrast(0.5);
    }

    .item-list>.header {
        background: var(--bg7);
        border-color: var(--bg4);
    }

    .areatable .group, .routetable .group {
        background: var(--bg7);
    }

    .comment .body {
        border-color: var(--bg1);
    }

    .comment .body .markdown {
        background: var(--bg4);
    }

    .comment.arrow .body::after {
        border-color: transparent var(--bg1);
    }

    td.sortby {
        background: var(--bg5);
    }

    .routetable tbody tr.hover td.sortby, .routetable tbody tr:hover td.sortby {
        background: var(--bg2);
    }

    th.sortby {
        background-color: var(--bg7) !important;
    }

    th.sortby a {
        color: var(--text4) !important;
    }

    .caret {
        border-top-color: var(--text4);
    }

    .responsive-iframe {
        filter: saturate(0.7) brightness(0.7);
    }

    .bigstats--borders .bigstats__stat>* {
        background: var(--bg10);
        border-color: var(--bg5);
    }

    .table th {
        color: var(--text4);
    }

    .table td, .table th {
        background: var(--bg6);
    }

    .table td>div {
        border-color: var(--bg5);
    }

    .table .rank1>td {
        background: #6a5d1f;
    }

    .table .rank2>td {
        background: #52595e;
    }

    .table .rank3>td {
        background: #765237;
    }

    .rank1 a .climber__name, .rank2 a .climber__name, .rank3 a .climber__name {
        color: var(--text1);
    }

    .SprdMain .customPageBackground {
        background-color: var(--bg10);
        color: var(--text4);
    }

    .sprd-c-s3 {
        color: var(--text4);
    }

    .sprd-bg-m1 {
        background-color: var(--bg9);
    }

    .sprd-bg-m3 {
        background-color: var(--bg9);
    }

    .SprdMain .sprd-btn-primary {
        background-color: var(--bg5);
        border-color: var(--bg3);
        color: var(--text2);
    }

    .SprdMain .sprd-btn-primary:hover {
        background-color: var(--bg3);
        border-color: var(--bg1);
    }

    .SprdMain .sprd-breadcrumb__link {
        color: var(--text4);
    }

    .SprdMain .sprd-breadcrumb__divider {
        color: var(--text4);
    }

    .sprd-bc-s2 {
        border-color: var(--bg1);
    }

    .SprdMain .sprd-pagination__page--current {
        background: var(--bg4) !important;
    }

    .sprd-lbc-s2 {
        border-color: var(--bg7);
    }

    .SprdMain .sprd-pagination__page--dots {
        background: none !important;
    }

    .SprdMain .sprd-pagination__button {
        background: var(--bg9);
        color: var(--text2);
    }

    .sprd-bc-m2 {
        border-color: var(--bg1);
    }

    .SprdMain .sprd-department-filter__entry:focus, 
    .SprdMain .sprd-department-filter__entry:hover {
        background-color: var(--bg3);
        color: var(--text1);
    }

    .ablock:hover, .aiblock:hover {
        color: var(--text4);
    }

    .bg-supporter-pale {
        background-color: var(--bg10);
    }

    kbd {
        background-color: var(--bg9);
        background-image: none;
        border-color: var(--bg4);
        box-shadow: none;
    }

    img {
        filter: var(--darken-img);
    }

    .bg-brand-blue-pale {
        background-color: var(--bg10);
    }

    .logos.logos--color span {
        background: var(--bg8) !important;
    }

    .tickTable .groupRow {
        background: var(--bg7);
    }

    form dt {
        background: var(--bg10);
    }

    .bigstats dl.gb0 {
        background-color: #414141 !important;
    }

    .bigstats dl.gb1 {
        background-color: #30521c !important;
    }

    .bigstats dl.gb2 {
        background-color: #695f1a !important;
    }

    .bigstats dl.gb3 {
        background-color: #6f4e1e !important;
    }

    .bigstats dl.gb4 {
        background-color: #872222 !important;
    }

    .bigstats dl.gb5 {
        background-color: #710d50 !important;
    }

    .comment .body {
        background: var(--bg4);
    }

    .comment.you .body {
        background: var(--bg1);
        border-color: var(--bg1);
    }

    .comment.you.arrow .body::after {
        border-color: transparent var(--bg1);
    }

    form.editMsg textarea.markdown:focus {
        color: var(--text2);
    }

    .node-listview .crumbtrail_group {
        background: var(--bg6);
    }

    .tickbar {
        color: var(--text5);
    }
}
